// Wrestler facts (Wikidata, CC0) and free-license photos (Wikimedia
// Commons), generated by scripts/fetch-wrestler-data.mjs.
import data from '../data/wrestler-facts.json';

export interface Photo { src: string; width: number; height: number; credit: string; license: string; license_url: string | null; source: string }
export interface Facts {
  qid: string | null; wikidata_label?: string | null; birth_name?: string | null; born?: string | null; died?: string | null;
  birthplace?: string | null; height_cm?: number | null; debut?: string | null; photo?: Photo | null;
}

const all = data as Record<string, Facts>;
export const factsFor = (slug: string): Facts => all[slug] ?? { qid: null };
export const allPhotos = () => Object.entries(all).filter(([, f]) => f.photo).map(([slug, f]) => ({ slug, photo: f.photo! }));

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
/** "1949-02-25" → "February 25, 1949"; "1949-02" → "February 1949"; "1949" → "1949" */
export function fmtFactDate(d?: string | null) {
  if (!d) return null;
  const [y, m, day] = d.split('-');
  if (!m) return y;
  if (!day) return `${MONTHS[Number(m) - 1]} ${y}`;
  return `${MONTHS[Number(m) - 1]} ${Number(day)}, ${y}`;
}
/** 191 → "6 ft 3 in (191 cm)" */
export function fmtHeight(cm?: number | null) {
  if (!cm) return null;
  const inches = Math.round(cm / 2.54);
  return `${Math.floor(inches / 12)} ft ${inches % 12} in (${cm} cm)`;
}
export function ageAt(born?: string | null, died?: string | null) {
  if (!born || born.length < 10) return null;
  const end = died && died.length >= 10 ? new Date(died) : new Date();
  const b = new Date(born);
  let age = end.getUTCFullYear() - b.getUTCFullYear();
  if (end.getUTCMonth() < b.getUTCMonth() || (end.getUTCMonth() === b.getUTCMonth() && end.getUTCDate() < b.getUTCDate())) age--;
  return age;
}
export const initials = (name: string) => name.replace(/"[^"]*"\s*/g, '').replace(/^(The|Dr\.)\s+/, '').split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join('').toUpperCase();
